using System.Drawing.Printing;
using System.Text;
namespace CardArchive;
public sealed class MainForm:Form
{
 readonly TextBox name=new(),number=new(),search=new();readonly DataGridView grid=new();readonly Label count=new();readonly Button save=new();readonly PrintDocument printer=new();List<Person> printRows=new();int printAt;long? editId;
 public MainForm(){Text="فهرس البطاقات الوطنية";Width=1100;Height=700;MinimumSize=new Size(900,580);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Tahoma",10);RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;BackColor=Color.FromArgb(245,247,250);
 var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),RowCount=4,ColumnCount=1};root.RowStyles.Add(new RowStyle(SizeType.Absolute,60));root.RowStyles.Add(new RowStyle(SizeType.Absolute,135));root.RowStyles.Add(new RowStyle(SizeType.Absolute,55));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);
 var head=new Panel{Dock=DockStyle.Fill};head.Controls.Add(new Label{Text="فهرس البطاقات الوطنية",Font=new Font("Tahoma",19,FontStyle.Bold),AutoSize=true,Location=new Point(0,5),ForeColor=Color.FromArgb(31,54,82)});count.Text="عدد السجلات: 0";count.AutoSize=true;count.Location=new Point(0,37);head.Controls.Add(count);root.Controls.Add(head,0,0);
 var group=new GroupBox{Text="إضافة / تعديل شخص",Dock=DockStyle.Fill,Padding=new Padding(10)};var form=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=2};form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,42));form.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,28));form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,110));form.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,110));form.RowStyles.Add(new RowStyle(SizeType.Absolute,30));form.RowStyles.Add(new RowStyle(SizeType.Percent,100));group.Controls.Add(form);form.Controls.Add(Lbl("اسم صاحب البطاقة"),0,0);form.Controls.Add(Lbl("رقم البطاقة"),1,0);Box(name);Box(number);form.Controls.Add(name,0,1);form.Controls.Add(number,1,1);save.Text="حفظ";Btn(save,Color.SeaGreen);save.Click+=(_,_)=>Save();form.Controls.Add(save,2,1);var clear=new Button{Text="تفريغ"};Btn(clear,Color.SlateGray);clear.Click+=(_,_)=>Clear();form.Controls.Add(clear,3,1);root.Controls.Add(group,0,1);
 var bar=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=5};bar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=1;i<5;i++)bar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,112));search.Dock=DockStyle.Fill;search.PlaceholderText="ابحث بالاسم أو رقم البطاقة...";search.TextChanged+=(_,_)=>RefreshRows();bar.Controls.Add(search,0,0);Tool(bar,"استيراد CSV",1,Import);Tool(bar,"تصدير CSV",2,Export);Tool(bar,"نسخ احتياطي",3,Backup);Tool(bar,"طباعة القائمة",4,PrintList);root.Controls.Add(bar,0,2);
 grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.RowHeadersVisible=false;grid.BackgroundColor=Color.White;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(31,54,82);grid.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;grid.Columns.Add(new DataGridViewTextBoxColumn{Name="Id",Visible=false});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="FullName",HeaderText="اسم صاحب البطاقة",FillWeight=60});grid.Columns.Add(new DataGridViewTextBoxColumn{Name="CardNumber",HeaderText="رقم البطاقة",FillWeight=40});grid.Columns.Add(new DataGridViewButtonColumn{Name="Edit",HeaderText="تعديل",Text="تعديل",UseColumnTextForButtonValue=true});grid.Columns.Add(new DataGridViewButtonColumn{Name="Delete",HeaderText="حذف",Text="حذف",UseColumnTextForButtonValue=true});grid.CellContentClick+=GridClick;grid.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0)Edit(e.RowIndex);};root.Controls.Add(grid,0,3);
 name.KeyDown+=Key;number.KeyDown+=Key;printer.PrintPage+=PrintPage;Load+=(_,_)=>{Database.Initialize();RefreshRows();name.Focus();};}
 static Label Lbl(string s)=>new(){Text=s,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight};static void Box(TextBox b){b.Dock=DockStyle.Fill;b.TextAlign=HorizontalAlignment.Right;b.Font=new Font("Tahoma",11);}static void Btn(Button b,Color c){b.Dock=DockStyle.Fill;b.BackColor=c;b.ForeColor=Color.White;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderSize=0;}void Tool(TableLayoutPanel p,string s,int col,Action a){var b=new Button{Text=s};Btn(b,Color.FromArgb(55,105,160));b.Click+=(_,_)=>a();p.Controls.Add(b,col,0);}
 void RefreshRows(){if(!IsHandleCreated)return;grid.Rows.Clear();foreach(var p in Database.Search(search.Text))grid.Rows.Add(p.Id,p.FullName,p.CardNumber,"تعديل","حذف");count.Text=$"عدد السجلات: {Database.Count():N0}";}
 void Save(){string n=name.Text.Trim(),c=number.Text.Trim();if(n==""||c==""){MessageBox.Show("يرجى إدخال الاسم ورقم البطاقة.");return;}try{if(editId.HasValue)Database.Update(editId.Value,n,c);else Database.Add(n,c);Clear();RefreshRows();name.Focus();}catch(Microsoft.Data.Sqlite.SqliteException ex)when(ex.SqliteErrorCode==19){MessageBox.Show("رقم البطاقة مسجل مسبقاً.");number.Focus();number.SelectAll();}catch(Exception ex){MessageBox.Show("تعذر الحفظ: "+ex.Message);}}
 void Key(object? s,KeyEventArgs e){if(e.KeyCode!=Keys.Enter)return;e.SuppressKeyPress=true;if(s==name)number.Focus();else Save();}void Edit(int r){editId=Convert.ToInt64(grid.Rows[r].Cells["Id"].Value);name.Text=Convert.ToString(grid.Rows[r].Cells["FullName"].Value);number.Text=Convert.ToString(grid.Rows[r].Cells["CardNumber"].Value);save.Text="حفظ التعديل";name.Focus();name.SelectAll();}void Clear(){editId=null;name.Clear();number.Clear();save.Text="حفظ";}
 void GridClick(object? s,DataGridViewCellEventArgs e){if(e.RowIndex<0||e.ColumnIndex<0)return;long id=Convert.ToInt64(grid.Rows[e.RowIndex].Cells["Id"].Value);if(grid.Columns[e.ColumnIndex].Name=="Edit")Edit(e.RowIndex);else if(grid.Columns[e.ColumnIndex].Name=="Delete"){string n=Convert.ToString(grid.Rows[e.RowIndex].Cells["FullName"].Value)??"";if(MessageBox.Show($"هل تريد حذف سجل ({n})؟","تأكيد الحذف",MessageBoxButtons.YesNo)==DialogResult.Yes){Database.Delete(id);if(editId==id)Clear();RefreshRows();}}}
 void Import(){using var d=new OpenFileDialog{Filter="CSV (*.csv)|*.csv|All files (*.*)|*.*"};if(d.ShowDialog()!=DialogResult.OK)return;try{var r=Database.ImportCsv(d.FileName);RefreshRows();MessageBox.Show($"أضيف: {r.added}\nمكرر: {r.duplicates}\nغير صالح: {r.invalid}","نتيجة الاستيراد");}catch(Exception ex){MessageBox.Show("تعذر الاستيراد: "+ex.Message);}}
 static string Csv(string s)=>"\""+s.Replace("\"","\"\"")+"\"";void Export(){using var d=new SaveFileDialog{Filter="CSV متوافق مع Excel (*.csv)|*.csv",FileName="فهرس_البطاقات.csv"};if(d.ShowDialog()!=DialogResult.OK)return;try{var b=new StringBuilder("الاسم,رقم البطاقة\r\n");foreach(var p in Database.Search())b.AppendLine(Csv(p.FullName)+","+Csv(p.CardNumber));File.WriteAllText(d.FileName,b.ToString(),new UTF8Encoding(true));MessageBox.Show("تم التصدير بنجاح.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void Backup(){using var d=new SaveFileDialog{Filter="قاعدة بيانات (*.db)|*.db",FileName=$"CardArchive_Backup_{DateTime.Now:yyyyMMdd_HHmm}.db"};if(d.ShowDialog()!=DialogResult.OK)return;try{Database.Backup(d.FileName);MessageBox.Show("تم إنشاء النسخة الاحتياطية.");}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void PrintList(){printRows=Database.Search(search.Text);if(printRows.Count==0){MessageBox.Show("لا توجد سجلات للطباعة.");return;}printAt=0;using var d=new PrintPreviewDialog{Document=printer,Width=1000,Height=750};d.ShowDialog(this);}
 void PrintPage(object? s,PrintPageEventArgs e){Graphics g=e.Graphics!;float x=e.MarginBounds.Left,y=e.MarginBounds.Top,w=e.MarginBounds.Width;using var title=new Font("Tahoma",16,FontStyle.Bold);using var f=new Font("Tahoma",9);using var pen=new Pen(Color.Black);g.DrawString("فهرس البطاقات الوطنية",title,Brushes.Black,x,y);y+=38;float[] widths={w*.1f,w*.58f,w*.32f};string[] heads={"ت","اسم صاحب البطاقة","رقم البطاقة"};for(int i=0;i<3;i++)Cell(g,heads[i],x+widths.Take(i).Sum(),y,widths[i],26,f,pen);y+=26;int idx=printAt+1;while(printAt<printRows.Count&&y+25<e.MarginBounds.Bottom){var p=printRows[printAt];string[] vals={idx.ToString(),p.FullName,p.CardNumber};for(int i=0;i<3;i++)Cell(g,vals[i],x+widths.Take(i).Sum(),y,widths[i],25,f,pen);y+=25;printAt++;idx++;}e.HasMorePages=printAt<printRows.Count;}
 static void Cell(Graphics g,string t,float x,float y,float w,float h,Font f,Pen p){g.DrawRectangle(p,x,y,w,h);using var fmt=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center,FormatFlags=StringFormatFlags.DirectionRightToLeft,Trimming=StringTrimming.EllipsisCharacter};g.DrawString(t,f,Brushes.Black,new RectangleF(x+2,y+2,w-4,h-4),fmt);}
